def task_has_image(task_name):
    """Check if a Task has at least one attached image File record."""
    exts = (".jpg", ".jpeg", ".png", ".gif", ".webp", ".heic", ".heif")
    files = frappe.get_all("File", filters={"attached_to_doctype": "Task", "attached_to_name": task_name}, fields=["file_url"])
    images = [f.file_url for f in files if (f.file_url or "").lower().split("?")[0].endswith(exts)]
    print(f"[Photo] task_has_image({task_name}): total_files={len(files)}, images={len(images)}, urls={images[:5]}")
    return len(images) > 0

before = doc.get_doc_before_save()
before_status = before.status if before else None
is_becoming_completed = (doc.status == "Completed" and before_status != "Completed")
DIRECTOR_ROLE = "Ops - Directors"

# Read role and team mappings from Task Access Policy (single source of truth)
allowed_roles = []
default_team = ""
policy = None
if doc.task_kind:
    try:
        policy = frappe.get_doc("Task Access Policy", doc.task_kind)
        allowed_roles = [r.role for r in (policy.allowed_roles or [])]
        default_team = policy.default_team_user or ""
    except Exception:
        pass

print(f"[Policy] {frappe.utils.now()} task={doc.name} kind={doc.task_kind} policy_found={'yes' if policy else 'no'} roles={len(allowed_roles)} default_team={default_team}")

def current_user_roles():
    return set(frappe.get_all("Has Role", filters={"parent": frappe.session.user}, pluck="role"))
def has_any_role(user_roles, allowed_roles):
    return any(r in user_roles for r in (allowed_roles or []))
def is_admin_override(user_roles):
    return bool("System Manager" in user_roles or "Ops - Directors" in user_roles or frappe.session.user == "Administrator")
def get_assigned_users(task_doc):
    try:
        return json.loads(task_doc.get("_assign") or "[]") or []
    except Exception:
        return []
def user_has_allowed_role(user, allowed_roles):
    user_roles = set(frappe.get_all("Has Role", filters={"parent": user}, pluck="role"))
    return any(r in user_roles for r in (allowed_roles or []))

# Default team user assignment: if task_kind is set and custom_assigned_to is empty, assign to default team user
if doc.task_kind and not doc.custom_assigned_to:
    if default_team:
        doc.custom_assigned_to = default_team
        print(f"[Policy] {frappe.utils.now()} task={doc.name} default_assign: team={default_team}")

# Always sync _assign from custom_assigned_to (single source of truth)
if doc.custom_assigned_to:
    doc.set("_assign", json.dumps([doc.custom_assigned_to]))
    print(f"[Policy] {frappe.utils.now()} task={doc.name} assign_sync: user={doc.custom_assigned_to}")
else:
    doc.set("_assign", "[]")

if doc.task_kind and not doc.task_access_policy:
    doc.task_access_policy = doc.task_kind
if doc.task_access_policy and not frappe.db.exists("Task Access Policy", doc.task_access_policy):
    frappe.throw("Task Access Policy '" + doc.task_access_policy + "' does not exist.")
user_roles = current_user_roles()
if before and doc.task_kind and not is_admin_override(user_roles):
    if not has_any_role(user_roles, allowed_roles):
        print(f"[Policy] {frappe.utils.now()} task={doc.name} role_check: user={frappe.session.user} allowed={allowed_roles} result=BLOCKED")
        frappe.throw("You are not allowed to edit Task Kind '" + doc.task_kind + "'.")
if is_becoming_completed and doc.task_kind and not is_admin_override(user_roles):
    if not has_any_role(user_roles, allowed_roles):
        print(f"[Policy] {frappe.utils.now()} task={doc.name} completing: user={frappe.session.user} allowed={allowed_roles} result=BLOCKED")
        frappe.throw("Only " + ", ".join(allowed_roles) + " can complete Task Kind '" + doc.task_kind + "'.")
# Old-flow mandatory attachments (only for tasks NOT linked to a Dispatch Case)
if not doc.dispatch_case:
    if is_becoming_completed and doc.task_kind == "Delivery":
        has_img = task_has_image(doc.name)
        print(f"[Photo] {frappe.utils.now()} task={doc.name} policy Delivery gate (no DC): has_image={has_img}, result={'PASS' if has_img else 'BLOCKED'}")
        if not has_img:
            frappe.throw("At least one photo is required to complete a Delivery task.")
    if is_becoming_completed and doc.task_kind == "Return drop-off at warehouse":
        has_img = task_has_image(doc.name)
        print(f"[Photo] {frappe.utils.now()} task={doc.name} policy Return drop-off gate (no DC): has_image={has_img}, result={'PASS' if has_img else 'BLOCKED'}")
        if not has_img:
            frappe.throw("At least one photo is required to complete a Return drop-off at warehouse task.")
assigned_users = get_assigned_users(doc)
is_becoming_working = (doc.status == "Working" and before_status != "Working")
# TEMPORARILY DISABLED FOR LAUNCH - assignment validation causes issues with accept workflow
# Will re-enable after launch when workflow is stable
# if doc.task_kind and doc.status not in ("Cancelled", "Open", "Working") and not is_becoming_working:
#     if len(assigned_users) != 1:
#         frappe.throw("Each operational task must be assigned to exactly 1 user. Current count: " + str(len(assigned_users)) + ".")
# if doc.task_kind and len(assigned_users) == 1 and allowed_roles:
#     owner = assigned_users[0]
#     if not user_has_allowed_role(owner, allowed_roles):
#         frappe.throw("Task Kind '" + doc.task_kind + "' must be assigned to a user in: " + ", ".join(allowed_roles) + ".")
# if is_becoming_completed:
#     if len(assigned_users) != 1:
#         frappe.throw("Assign exactly 1 owner before completing this task.")
if is_becoming_completed and not doc.completed_at:
    doc.completed_at = frappe.utils.now_datetime()

if doc.director_approval_status != "Approved":
    frappe.throw(
        "Director approval is required before submitting the Purchase Order. "
        "Create a Purchase Approval task, get it completed as Approved, then submit."
    )

MAIN_WH = "Main - Inmed"

for row in (doc.items or []):
    if row.warehouse != MAIN_WH:
        frappe.throw(f"Receiving must be into {MAIN_WH}. Row warehouse is {row.warehouse or 'not set'}.")

    if not row.item_code:
        continue

    item = frappe.get_doc("Item", row.item_code)

    requires_expiry = bool(item.get("has_expiry_date"))
    has_batch = bool(item.get("has_batch_no"))

    if requires_expiry and has_batch:
        if not row.batch_no:
            frappe.throw(f"Row for item {row.item_code} requires Batch + Expiry. Batch No is missing.")

        batch = frappe.get_doc("Batch", row.batch_no)
        if not batch.expiry_date:
            frappe.throw(f"Batch {row.batch_no} must have Expiry Date for item {row.item_code}.")

if doc.supplier:
    for row in (doc.items or []):
        if not row.item_code:
            continue

        suppliers = frappe.get_all(
            "Item Supplier",
            filters={"parent": row.item_code, "parenttype": "Item"},
            pluck="supplier",
        )

        suppliers = [s for s in (suppliers or []) if s]

        if len(suppliers) != 1:
            frappe.throw(
                f"Item {row.item_code} must have exactly 1 Supplier (Doc 07 policy). Found: {', '.join(suppliers) or 'none'}."
            )

        if suppliers[0] != doc.supplier:
            frappe.throw(
                f"Item {row.item_code} supplier is {suppliers[0]} but PO supplier is {doc.supplier}. Do not mix suppliers on one PO."
            )

before = doc.get_doc_before_save()
if before:
    def snap(rows):
        return [(r.warehouse, r.warehouse_reorder_level or 0, r.warehouse_reorder_qty or 0) for r in (rows or [])]
    if snap(before.reorder_levels) != snap(doc.reorder_levels):
        if not (doc.reorder_change_reason or "").strip():
            frappe.throw("Doc 08: Reorder Change Reason required.")

before = doc.get_doc_before_save()

if not before:
    pass
else:
    # Standard ERPNext fieldname for Item Reorder child table.
    # If your instance uses a different name, change this value.
    REORDER_FIELDNAME = "reorder_levels"

    def normalize(rows):
        out = []
        for r in (rows or []):
            out.append({
                "warehouse": r.warehouse,
                "reorder_level": float(getattr(r, "warehouse_reorder_level", 0) or 0),
                "reorder_qty": float(getattr(r, "warehouse_reorder_qty", 0) or 0),
            })
        return out

    before_rows = normalize(before.get(REORDER_FIELDNAME) or [])
    after_rows  = normalize(doc.get(REORDER_FIELDNAME) or [])

    if before_rows != after_rows:
        if not (doc.reorder_change_reason or "").strip():
            frappe.throw(
                "Reorder Change Reason is required when changing reorder thresholds "
                "(Doc 08 governance rule)."
            )

def task_has_image(task_name):
    """Check if a Task has at least one attached image File record."""
    exts = (".jpg", ".jpeg", ".png", ".gif", ".webp", ".heic", ".heif")
    files = frappe.get_all("File", filters={"attached_to_doctype": "Task", "attached_to_name": task_name}, fields=["file_url"])
    images = [f.file_url for f in files if (f.file_url or "").lower().split("?")[0].endswith(exts)]
    print(f"[Photo] task_has_image({task_name}): total_files={len(files)}, images={len(images)}, urls={images[:5]}")
    return len(images) > 0

# Mandatory: task must be accepted before any save/change/complete
if doc.task_kind and doc.status != "Template" and doc.status != "Cancelled":
    accept_gate_before = doc.get_doc_before_save()
    accept_gate_is_new = not accept_gate_before
    if not accept_gate_is_new and not doc.custom_accepted_by:
        print(f"[Gates] {frappe.utils.now()} task={doc.name} gate=acceptance kind={doc.task_kind} accepted_by= result=BLOCKED")
        frappe.throw("You must Accept this task before making any changes or completing it.")

# Sync customer from Task to Dispatch Case
if doc.dispatch_case and doc.customer:
    dc_customer = frappe.db.get_value("Dispatch Case", doc.dispatch_case, "customer")
    if not dc_customer:
        frappe.db.set_value("Dispatch Case", doc.dispatch_case, "customer", doc.customer)
# Global: cannot complete a task unless you are assigned to it
before = doc.get_doc_before_save()
before_status = before.status if before else None
is_completing_global = (doc.status == "Completed" and before_status != "Completed")
if is_completing_global:
    # Block completion if assignment is being changed in the same save
    old_assigned_user = before.custom_assigned_to if before else None
    if (doc.custom_assigned_to or "") != (old_assigned_user or ""):
        frappe.throw("You cannot reassign and complete a task at the same time. Save the reassignment first.")
    accepted_by = doc.custom_accepted_by or frappe.db.get_value("Task", doc.name, "custom_accepted_by")
    if not accepted_by and frappe.session.user != "Administrator":
        print(f"[Gates] {frappe.utils.now()} task={doc.name} gate=completion kind={doc.task_kind} user={frappe.session.user} accepted_by= result=BLOCKED")
        frappe.throw("You must accept this task before completing it. Click Accept / Start Task first.")
    if accepted_by and accepted_by != frappe.session.user and frappe.session.user != "Administrator":
        print(f"[Gates] {frappe.utils.now()} task={doc.name} gate=completion kind={doc.task_kind} user={frappe.session.user} accepted_by={accepted_by} result=BLOCKED")
        frappe.throw("Only the user who accepted this task (" + accepted_by + ") can complete it.")

# Order entry completion: require submitted Dispatch Case
before = doc.get_doc_before_save()
before_status = before.status if before else None
is_completing_early = (doc.status == "Completed" and before_status != "Completed")
if is_completing_early and doc.task_kind == "Order entry":
    if not doc.dispatch_case:
        frappe.throw("Link a Dispatch Case before completing the Order entry task.")
    dc_docstatus = frappe.db.get_value("Dispatch Case", doc.dispatch_case, "docstatus")
    if dc_docstatus != 1:
        dc_doc = frappe.get_doc("Dispatch Case", doc.dispatch_case)
        if not dc_doc.items or len(dc_doc.items) == 0:
            frappe.throw("Add at least one product to the Dispatch Case before completing.")
        dc_doc.submit()

if not doc.dispatch_case:
    pass
else:
    # Update dispatch_case_status field for display
    if doc.dispatch_case:
        dc_status = frappe.db.get_value("Dispatch Case", doc.dispatch_case, "status")
        if dc_status:
            doc.dispatch_case_status = dc_status
    before = doc.get_doc_before_save()
    before_status = before.status if before else None
    before_ds = (before.delivery_status if before else None) or "Todo"
    before_ps = (before.pickup_status if before else None) or "Todo"
    is_completing = (doc.status == "Completed" and before_status != "Completed")
    ds_changing = (doc.task_kind == "Delivery" and doc.delivery_status != before_ds)
    ps_changing = (doc.task_kind == "Pickup Returns" and doc.pickup_status != before_ps)

    # Pack task: require at least one image before completing
    if is_completing and doc.task_kind == "Pack / prepare items":
        has_photo = task_has_image(doc.name)
        print(f"[Photo] {frappe.utils.now()} task={doc.name} Pack completion gate: has_image={has_photo}, result={'PASS' if has_photo else 'BLOCKED'}")
        if not has_photo:
            frappe.throw("At least one photo is required before completing the Pack / prepare items task.")

    # Delivery: must go through Picked Up before Delivered
    if ds_changing and doc.delivery_status == "Delivered" and before_ds != "Picked Up":
        frappe.throw("Delivery status must be changed to 'Picked Up' and saved before it can be marked as 'Delivered'.")

    # Delivery: can't complete unless delivery_status is Delivered
    if is_completing and doc.task_kind == "Delivery" and doc.delivery_status != "Delivered":
        frappe.throw("Delivery task cannot be completed until delivery status is 'Delivered'.")

    # Auto-complete Delivery task when marked Delivered
    if ds_changing and doc.delivery_status == "Delivered":
        doc.status = "Completed"

    # Pickup Returns: must go through Picked Up before Returned to Warehouse
    if ps_changing and doc.pickup_status == "Returned to Warehouse" and before_ps != "Picked Up":
        frappe.throw("Pickup status must be changed to 'Picked Up' and saved before it can be marked as 'Returned to Warehouse'.")

    # Pickup Returns: can't complete unless pickup_status is Returned to Warehouse
    if is_completing and doc.task_kind == "Pickup Returns" and doc.pickup_status != "Returned to Warehouse":
        frappe.throw("Pickup Returns task cannot be completed until pickup status is 'Returned to Warehouse'.")

    # Auto-complete Return Pickup task when Returned to Warehouse
    if ps_changing and doc.pickup_status == "Returned to Warehouse":
        has_dropoff = task_has_image(doc.name)
        print(f"[Photo] {frappe.utils.now()} task={doc.name} Pickup Returns dropoff gate: has_image={has_dropoff}, result={'PASS' if has_dropoff else 'BLOCKED'}")
        if not has_dropoff:
            frappe.throw("At least one photo is required before marking Returned to Warehouse.")
        doc.status = "Completed"

    # Pack completion: all items must be checked as packed
    if doc.status == "Completed" and doc.task_kind == "Pack / prepare items":
        case = frappe.get_doc("Dispatch Case", doc.dispatch_case)
        not_packed = []
        for row in (case.case_items or []):
            status = row.custom_packing_status or 'Pending'
            if status not in ('Complete', 'Over Scanned'):
                not_packed.append(row.item_code or row.item_name or 'Unknown')
        if not_packed:
            frappe.throw('All items must be packed before completing this task. Not packed: ' + ', '.join(not_packed))

    # Returns Inspection completion: require returned_qty
    if is_completing and doc.task_kind == "Returns processing / verification":
        case = frappe.get_doc("Dispatch Case", doc.dispatch_case)
        for row in (case.case_items or []):
            if row.returned_qty is None:
                frappe.throw("Fill returned_qty for ALL items in Dispatch Case before completing.")

    # Invoice Preparation completion: require submitted invoice
    if is_completing and doc.task_kind == "Invoice preparation / create invoice":
        inv = frappe.db.get_value("Dispatch Case", doc.dispatch_case, "sales_invoice")
        if not inv:
            frappe.throw("No Sales Invoice linked to this Dispatch Case yet.")
        if frappe.db.get_value("Sales Invoice", inv, "docstatus") != 1:
            frappe.throw("Submit the Sales Invoice before completing this task.")

    # Discount Approval completion: require approval_outcome
    if is_completing and doc.task_kind == "Discount Approval":
        if not doc.approval_outcome:
            frappe.throw("Set Approval Outcome (Approved or Rejected) before completing.")

    # Debt Closure Approval: only Norayr, Sevak, or Levon can complete
    if is_completing and doc.task_kind == "Debt Closure Approval":
        APPROVED_USERS = ["ghahramanyann@gmail.com", "karapetyansev@gmail.com", "vahe.muselimyan@gmail.com", "levonaghinyan77@gmail.com"]
        if frappe.session.user not in APPROVED_USERS and frappe.session.user != "Administrator":
            frappe.throw("Only Norayr, Sevak, or Levon can approve and complete this task.")

if doc.task_kind != "Debt Collection":
    pass
elif not (doc.new_payment_amount or 0) > 0:
    pass
else:
    before = doc.get_doc_before_save()
    before_amt = (before.new_payment_amount if before else None) or 0
    if doc.new_payment_amount == before_amt:
        pass
    else:
        amount = doc.new_payment_amount
        method = doc.payment_method_dc or "Cash"
        ref = doc.payment_reference_dc or ""
        remaining = amount
        for row in sorted(doc.open_invoices, key=lambda r: r.sales_invoice):
            to_apply = min(remaining, row.outstanding_amount or 0)
            row.allocated_now = to_apply
            remaining -= to_apply
            if remaining <= 0:
                break
        for row in doc.open_invoices:
            apply = row.allocated_now or 0
            if apply > 0:
                row.paid_amount = (row.paid_amount or 0) + apply
                row.outstanding_amount = (row.outstanding_amount or 0) - apply
                row.allocated_now = 0
        doc.total_outstanding = sum((r.outstanding_amount or 0) for r in doc.open_invoices)
        doc.append("payment_history", {
            "payment_date": frappe.utils.now_datetime(),
            "amount": amount,
            "method": method,
            "reference": ref,
        })
        pe = frappe.get_doc({
            "doctype": "Payment Entry",
            "payment_type": "Receive",
            "party_type": "Customer",
            "party": doc.customer,
            "paid_amount": amount,
            "received_amount": amount,
            "mode_of_payment": method,
            "reference_no": ref,
            "reference_date": frappe.utils.nowdate(),
            "company": "InMED",
            "paid_to": "Cash - Inmed",
        })
        for row in doc.open_invoices:
            if (row.allocated_now or 0) > 0:
                pe.append("references", {
                    "reference_doctype": "Sales Invoice",
                    "reference_name": row.sales_invoice,
                    "allocated_amount": row.allocated_now,
                })
        pe.flags.ignore_permissions = True
        pe.insert()
        pe.submit()
        if doc.payment_history:
            frappe.db.set_value("Debt Collection Payment", doc.payment_history[-1].name, "payment_entry", pe.name)
        doc.new_payment_amount = 0
        doc.payment_method_dc = ""
        doc.payment_reference_dc = ""
        if doc.total_outstanding <= 0:
            doc.status = "Completed"

for row in (doc.case_items or []):
    dispatched = row.dispatched_qty or 0
    returned = row.returned_qty or 0
    lost = row.lost_damaged_qty or 0
    row.used_qty = dispatched - returned - lost
    if row.used_qty < 0:
        frappe.throw(f"Row {row.idx}: used_qty cannot be negative (dispatched={dispatched}, returned={returned}, lost={lost}).")
if doc.status == "Draft":
    has_discount = any(float(row.discount_pct or 0) > 0 for row in (doc.case_items or []))
    if has_discount:
        doc.status = "Awaiting Approval"
        doc.discount_approval_status = "Pending"

if not doc.case_items:
	frappe.throw('Add at least one item before submitting.')
if doc.status not in ('Draft', 'Confirmed'):
	frappe.throw('Cannot submit a Dispatch Case in status: ' + doc.status)
if doc.status == 'Draft':
	doc.status = 'Confirmed'
# Do NOT create Pack task here - it will be created when Order Entry task is completed

# Only check for packing problems if a pack task exists (packing has started)
if doc.get("pack_task"):
    problem_rows = []
    for row in doc.get("case_items") or []:
        required = float(row.get("dispatched_qty") or 0)
        scanned = float(row.get("custom_scanned_qty") or 0)
        status = row.get("custom_packing_status")
        reason = row.get("custom_problem_reason") or row.get("custom_scan_note") or ""
        if status == "Problem" or (scanned < required and status in ("Partial", "Pending")):
            problem_rows.append({"item_code": row.get("item_code"), "required": required, "scanned": scanned, "reason": reason, "row_name": row.name})
    if not problem_rows:
        if doc.get("custom_packing_problem_status") and doc.get("custom_packing_problem_status") != "No Problem":
            frappe.db.set_value("Dispatch Case", doc.name, {"custom_packing_problem_status": "No Problem", "custom_packing_problem_summary": ""}, update_modified=False)
    else:
        summary_parts = []
        for p in problem_rows[:5]:
            missing = p["required"] - p["scanned"]
            if missing < 0:
                missing = 0
            part = str(p["item_code"] or "Unknown Item") + " missing " + str(missing)
            if p["reason"]:
                part += " (" + str(p["reason"]) + ")"
            summary_parts.append(part)
        summary = "; ".join(summary_parts)
        updates = {"custom_packing_problem_status": "Problem Open", "custom_packing_problem_summary": summary}
        frappe.db.set_value("Dispatch Case", doc.name, updates, update_modified=False)
        if not doc.get("custom_problem_alert_sent"):
            manager_roles = ["Ops - Inventory Manager", "Ops - Directors", "System Manager"]
            users = []
            for role in manager_roles:
                role_users = frappe.get_all("Has Role", filters={"role": role, "parenttype": "User"}, pluck="parent")
                for user in role_users or []:
                    if user not in users and frappe.db.get_value("User", user, "enabled"):
                        users.append(user)
            created = 0
            for user in users:
                exists = frappe.db.exists("ToDo", {"reference_type": "Dispatch Case", "reference_name": doc.name, "allocated_to": user, "status": "Open", "description": ["like", "Packing problem:%"]})
                if exists:
                    continue
                todo = frappe.new_doc("ToDo")
                todo.status = "Open"
                todo.allocated_to = user
                todo.reference_type = "Dispatch Case"
                todo.reference_name = doc.name
                todo.description = "Packing problem: " + summary
                todo.assigned_by = frappe.session.user
                todo.insert(ignore_permissions=True)
                created += 1
            if created:
                frappe.db.set_value("Dispatch Case", doc.name, "custom_problem_alert_sent", 1, update_modified=False)
                for row in doc.get("case_items") or []:
                    if row.get("custom_packing_status") == "Problem":
                        frappe.db.set_value("Dispatch Case Item", row.name, "custom_problem_alert_sent", 1, update_modified=False)

def run_script():
    task_name = frappe.form_dict.get('task_name')
    if not task_name:
        frappe.throw('Task is required.')
    task = frappe.get_doc('Task', task_name)
    if task.get('dispatch_case'):
        frappe.response['message'] = {'ok': True, 'dispatch_case': task.dispatch_case, 'created': False}
        return
    case = frappe.new_doc('Dispatch Case')
    if task.get('customer'):
        case.customer = task.customer
    case.status = 'Draft'
    case.order_entry_task = task_name
    if task.get('description'):
        case.notes = 'Created from Task ' + task.name + '\n\n' + task.description
    else:
        case.notes = 'Created from Task ' + task.name
    case.flags.ignore_permissions = True
    case.flags.ignore_mandatory = True
    case.insert()
    frappe.db.set_value('Task', task_name, 'dispatch_case', case.name)
    frappe.response['message'] = {'ok': True, 'dispatch_case': case.name, 'created': True}
run_script()

def run_script():
    barcode = (frappe.form_dict.get("barcode") or "").strip()
    if not barcode:
        frappe.throw("Barcode is required.")
    item_code = None
    if frappe.db.exists("Item", barcode):
        item_code = barcode
